withinTransaction(async () => {
  const tracks = song.tracks;
  for (let i = 0; i < tracks.length; i++) {
    const track = tracks[i];
    for (let j = track.arrangementClips.length - 1; j >= 0; j--) {
      await track.arrangementClips[j].delete();
    }
  }
});

